async function request(path,data){
 if(localTransport)return localTransport(path,data);
 const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),data===undefined?15000:30000);
 try{const response=await fetch(new URL(path.replace(/^\//,''),BASE_URL),{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'content-type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal});
  let value;try{value=await response.json()}catch{throw new Error('The server response was interrupted. Its recorded state must be checked before retrying.')}
  if(!response.ok){const error=new Error(value.error?.message||'The request could not be completed.');error.code=value.error?.code;throw error}return value;
 }finally{clearTimeout(timer)}
}
function operationMarkup(){
 const op=state?.operation,active=operationActive(state);
 if(!busy&&!active&&!recovering&&!state?.readinessChecking)return '';
 const elapsed=op?.startedAt&&active?Math.max(0,Math.floor((Date.now()-Date.parse(op.startedAt))/1000)):0;
 const phase=recovering?'Connection interrupted. Checking recorded state before any retry.':active?(op?.phase||'Working on the server'):state?.readinessChecking?'Checking existing provider connections':busy==='check'?'Checking existing provider connections':'Sending request to the server';
 return `<div class="operation-banner" role="status" aria-live="polite"><span class="spinner"></span><div><strong>${esc(phase)}</strong><p>${active?`<span data-operation-elapsed aria-live="off">${elapsed}s</span> elapsed · ${op?.status==='cancelling'?'Cancellation requested; upstream work may continue.':'You can leave this page and return. No automatic inference retries.'}`:state?.readinessChecking?'Read-only checks only. This does not establish inference success.':'No operation is repeated until its saved state is known.'}</p></div>${active&&op?.cancellable&&op.status==='running'?`<button class="plain-button" data-action="cancel-operation"${disabled(cancelPending)}>Cancel</button>`:recovering?'<button class="plain-button" data-action="reconnect">Check now</button>':''}</div>`;
}
function updateRuntimeUI(){const holder=$('#operation-status');if(holder){const signature=JSON.stringify([state?.operation?.id,state?.operation?.status,state?.operation?.phase,state?.operation?.cancellable,busy,recovering,state?.readinessChecking,cancelPending]);if(holder.dataset.signature!==signature){holder.innerHTML=operationMarkup();holder.dataset.signature=signature}else{const elapsed=$('[data-operation-elapsed]',holder);if(elapsed&&state.operation?.startedAt)elapsed.textContent=`${Math.max(0,Math.floor((Date.now()-Date.parse(state.operation.startedAt))/1000))}s`}}for(const provider of state?.readiness||[]){const row=$(`[data-provider-id="${provider.id}"]`);if(row){const detail=$('.adapter-copy p',row),pill=$('.pill',row);if(detail)detail.textContent=provider.detail;if(pill){pill.textContent=provider.status.replaceAll('_',' ');pill.className=`pill ${provider.status==='ready'?'positive':'neutral'}`}}}const label=$('.connection-button span:nth-child(2)');if(label)label.textContent=`${state?.readiness?.filter(r=>r.status==='ready').length||0}/3 connected`;}
// A late response must never dismiss a newer dialog or pull focus out of it.
function closeRequestModal(context){if(context&&modalRevision===context.modalRevision)closeModal()}
function finishPendingFromState(){
 const pending=pendingAction;pendingAction=null;busy=null;recovering=false;cancelPending=false;
 const matches=!!pending&&state.operation?.id!==pending.previousOperationId&&state.operation?.type===pending.name;if(matches&&state.operation?.status==='succeeded'&&['generate','correct'].includes(pending.name)&&mode===pending.mode&&selectedVersionId===pending.selectedVersionId){const latest=state.versions?.filter(v=>v.mode===mode).at(-1);if(latest)selectedVersionId=latest.id;}
 if(matches&&state.operation?.status==='succeeded')closeRequestModal(pending);
 render();const op=state.operation;if(op?.status==='cancelled')toast('Local operation cancelled. A provider request may still finish upstream.');else if(op?.status==='failed')toast(op.error?.message||'The operation stopped without publishing new results.',true);else if(matches&&op?.status==='succeeded')toast('Loaded the completed operation from saved server state.');else if(pending&&!matches)toast('No completed result was found for this request. Review saved state before retrying.',true);
}
async function refreshRecordedState(){
 if(localTransport)return;try{const before=operationActive(state),checking=state?.readinessChecking;state=await request('/api/state');recovering=false;
  if(operationActive(state)){busy=state.operation?.type||'remote';updateRuntimeUI()}
  else if(!localRequestInFlight&&(pendingAction||before)){finishPendingFromState()}
  else if(!localRequestInFlight){busy=null;if(checking!==state.readinessChecking)render();else updateRuntimeUI()}
  schedulePoll();
 }catch{if(pendingAction||operationActive(state)){recovering=true;busy='recovering';updateRuntimeUI();schedulePoll()}}
}
function schedulePoll(){clearTimeout(pollTimer);if(!localTransport&&(pendingAction||operationActive(state)||state?.readinessChecking||recovering))pollTimer=setTimeout(refreshRecordedState,document.hidden?8000:2500)}
async function action(name,path,data,success){
 if(busy||operationActive(state)||recovering)return;busy=name;pendingAction={name,startedAt:Date.now(),previousOperationId:state.operation?.id,mode,selectedVersionId,modalRevision};const requestContext=pendingAction;localRequestInFlight=true;render();schedulePoll();
 try{const out=await request(path,data);const contextUnchanged=mode===requestContext.mode&&selectedVersionId===requestContext.selectedVersionId&&modalRevision===requestContext.modalRevision;state=out.state||out;if(['generate','correct'].includes(name)&&mode===requestContext.mode&&selectedVersionId===requestContext.selectedVersionId)selectedVersionId=out.result?.id||state.versions.filter(v=>v.mode===mode).at(-1)?.id;localRequestInFlight=false;pendingAction=null;busy=operationActive(state)?state.operation?.type||'remote':null;recovering=false;closeRequestModal(requestContext);render();schedulePoll();const focusAction={generate:'evaluate',correct:'evaluate',publish:'replay',replay:'evidence',evaluate:currentEval()?.metrics.correct===currentEval()?.metrics.total?'publish':'correct'}[name];if(focusAction&&contextUnchanged&&!modalName){const completedModalRevision=modalRevision;requestAnimationFrame(()=>{if(!modalName&&modalRevision===completedModalRevision)$(`[data-action="${focusAction}"]:not(:disabled)`)?.focus()})}if(success)toast(typeof success==='function'?success(out):success);return out;
 }catch(error){localRequestInFlight=false;
  if(localTransport){busy=null;pendingAction=null;render();toast(error.message,true);return}
  try{state=await request('/api/state');recovering=false;if(operationActive(state)){busy=state.operation?.type||name;closeRequestModal(requestContext);render();toast('The server is still working. Tracking its saved status without repeating the request.');schedulePoll()}
   else{const recordedSuccess=state.operation?.status==='succeeded'&&state.operation?.type===name&&state.operation?.id!==requestContext.previousOperationId;if(recordedSuccess){finishPendingFromState()}else{busy=null;pendingAction=null;render();toast(error.message,true)}}
  }catch{recovering=true;busy='recovering';closeRequestModal(requestContext);render();toast('Connection interrupted. Checking saved state before allowing another operation.',true);schedulePoll()}
 }
}
