function clipCard(c){return `<button class="clip-card ${c.id===selectedClipId?'selected':''}" data-action="clip" data-id="${esc(c.id)}" aria-pressed="${c.id===selectedClipId}"><div class="clip-thumb"><img src="${esc(poster(c))}" alt="${c.mode==='demo'?'Synthetic traffic scene':'Corpus evidence'}: ${esc(c.title)}" loading="lazy"><span class="clip-type pill ${c.label?'positive':'negative'}">${c.label?'+ Positive':'− Hard negative'}</span><span class="clip-play">${icon('play',13)}</span><span class="clip-duration">${c.duration?fmtTime(c.duration):'LIVE'}</span></div><div class="clip-info"><span class="selection-dot"></span><div><strong>${esc(c.title)}</strong><span>${c.label?'The event to notice':'The boundary to learn'} · TRAIN</span></div></div></button>`}
